<script>
  import { onMount } from 'svelte';
  import { ArrowUpRight, ArrowLeft, BookOpen, Search, SlidersHorizontal, X, ChevronRight, Sparkles, Atom, Globe2, Bookmark, GraduationCap, Layers3, Target, Moon, Sun } from 'lucide-svelte';
  let data = $state(null), query = $state(''), subject = $state('all'), grade = $state('all'), field = $state('all'), selected = $state(null), saved = $state([]), theme = $state('dark');
  let records = $derived([...(data?.topicRecords || []), ...(data?.authoredModules || []).map(x => ({...x, authored:true, keyTerms:x.terms, formulas:x.formula ? [x.formula] : [], workedExamples:x.example ? [{question:x.example.q, steps:x.example.work, answer:x.example.a}] : [], commonErrors:x.errors, questionPatterns:x.questionPatterns, explanation:x.explanation}))]);
  let fields = $derived([...new Set(records.filter(x => subject==='all' || x.subject===subject).map(x=>x.field).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja')));
  let shown = $derived(records.filter(x => (subject==='all'||x.subject===subject) && (grade==='all'||String(x.grade)===grade) && (field==='all'||x.field===field) && (!query || [x.title,x.field,x.explanation,...(x.keyTerms||[]).map(t=>Array.isArray(t)?t.join(' '):t)].filter(Boolean).join(' ').toLowerCase().includes(query.toLowerCase()))));
  onMount(async()=>{try{theme=localStorage.getItem('manabixx-theme')||'dark';document.documentElement.dataset.theme=theme;saved=JSON.parse(localStorage.getItem('manabixx-library-saved')||'[]');const r=await fetch('/data/knowledge-base.json');if(!r.ok)throw new Error('教材データを読み込めませんでした');data=await r.json();}catch(e){console.error(e);}});
  function toggleTheme(){theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('manabixx-theme',theme);}
  function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('manabixx-library-saved',JSON.stringify(saved));}
</script>
<svelte:head><title>教材ライブラリ — MANABIXX</title><meta name="description" content="理科・社会の単元、重要語句、公式、実験、典型問題を横断して学べる教材ライブラリ。"/><meta name="theme-color" content="#090b0a"/></svelte:head>
<div class="study-app">
  <aside class="rail">
    <a href="/" class="mark" aria-label="MANABIXX Study"><span>M</span><i></i></a>
    <nav class="rail-links" aria-label="メインメニュー">
      <a class="rail-link" href="/" aria-label="ホーム"><Layers3 size={19}/></a>
      <a class="rail-link" href="/#question-bank" aria-label="問題演習"><Target size={19}/></a>
      <a class="rail-link selected" href="/library/" aria-label="教材ライブラリ"><BookOpen size={19}/></a>
      <a class="rail-link" href="/summary/" aria-label="要点まとめ"><BookOpen size={19}/></a>
      <a class="rail-link" href="/exam/" aria-label="入試問題"><GraduationCap size={19}/></a>
    </nav>
    <div class="rail-bottom"><button class="rail-link" onclick={toggleTheme} aria-label="テーマ切替">{#if theme==='dark'}<Sun size={19}/>{:else}<Moon size={19}/>{/if}</button><div class="rail-avatar">S</div></div>
  </aside>
  <div class="workspace">
    <header class="topline"><div class="crumb"><span>MANABIXX</span><b>/</b> STUDY <b>/</b> LIBRARY</div><div class="topline-right"><span class="live-dot">LEARNING SPACE</span><button class="theme-toggle" onclick={toggleTheme} aria-label="テーマ切替">{#if theme==='dark'}<Sun size={17}/>{:else}<Moon size={17}/>{/if}</button></div></header>
    <main class="page-wrap">
      <section class="intro"><div><div class="eyebrow"><Sparkles size={14}/> KNOWLEDGE ARCHIVE / 01</div><h1>知識を、<em>使える力に。</em></h1><p>単元を探す。仕組みを理解する。解ける知識へ変えていく。</p></div><div class="intro-mark"><BookOpen size={32}/><span>MX / LIBRARY</span></div></section>
      <section class="overview"><div><span>ALL TOPICS</span><strong>{records.length.toLocaleString('ja-JP')}</strong><small>登録コンテンツ</small></div><div><span>SCIENCE</span><strong>{records.filter(x=>x.subject==='science').length}</strong><small>理科</small></div><div><span>SOCIAL STUDIES</span><strong>{records.filter(x=>x.subject==='social').length}</strong><small>社会</small></div><div><span>DETAILED NOTES</span><strong>{records.filter(x=>x.authored||x.status==='authored').length}</strong><small>解説付き教材</small></div></section>
      <div class="catalog-head"><div><div class="eyebrow">EXPLORE CONTENTS</div><h2>教材を探す</h2><p>キーワードや教科、学年から必要な単元へ。</p></div><div class="result-count">{shown.length.toLocaleString('ja-JP')} <small>件を表示</small></div></div>
      <section class="filters"><label class="search"><Search size={18}/><input bind:value={query} placeholder="単元名・用語・内容から検索"/>{#if query}<button onclick={()=>query=''} aria-label="検索をクリア"><X size={15}/></button>{/if}</label><div class="filter-row"><label><span>教科</span><select bind:value={subject}><option value="all">すべて</option><option value="science">理科</option><option value="social">社会</option></select></label><label><span>学年</span><select bind:value={grade}><option value="all">全学年</option><option value="1">中学1年</option><option value="2">中学2年</option><option value="3">中学3年</option></select></label><label><span>分野</span><select bind:value={field}><option value="all">すべての分野</option>{#each fields as f}<option value={f}>{f}</option>{/each}</select></label><button class="clear" onclick={()=>{subject='all';grade='all';field='all';query='';}}>条件をリセット <SlidersHorizontal size={14}/></button></div></section>
      {#if !data}<div class="empty"><div class="loader"></div>教材データを読み込んでいます</div>{:else if shown.length===0}<div class="empty">条件に一致する教材がありません。検索語や絞り込みを変更してください。</div>{:else}
        <div class="cards">{#each shown as item,i}<article class:expanded={selected===item.id}><div class="card-top"><span class:science={item.subject==='science'} class:social={item.subject==='social'} class="subject">{#if item.subject==='science'}<Atom size={13}/> 理科{:else}<Globe2 size={13}/> 社会{/if}</span><span class="grade">中学{item.grade||'全'}年 · {item.field||'総合'}</span><button class:bookmarked={saved.includes(item.id)} class="save" onclick={()=>toggleSave(item.id)} aria-label="保存"><Bookmark size={16}/></button></div><h3>{item.title}</h3><p class="description">{item.explanation || (item.targets?.length ? item.targets.join('・') : 'この単元の重要事項・用語・典型的な考え方を整理するための学習項目です。')}</p><div class="card-bottom"><span class:complete={item.authored||item.status==='authored'}>{item.authored||item.status==='authored'?'DETAILED NOTE':'TOPIC INDEX'}</span><button onclick={()=>selected=selected===item.id?null:item.id}>{selected===item.id?'閉じる':'内容を見る'} <ChevronRight size={15}/></button></div>
          {#if selected===item.id}<div class="detail"><div class="detail-title">学習ポイント</div>{#if item.keyTerms?.length}<h4>重要語句</h4><div class="terms">{#each item.keyTerms as term}<span><b>{Array.isArray(term)?term[0]:term}</b>{#if Array.isArray(term)}<small>{term[1]}</small>{/if}</span>{/each}</div>{/if}{#if item.formulas?.length}<h4>公式・関係</h4>{#each item.formulas as f}<p>{f}</p>{/each}{/if}{#if item.workedExamples?.length}<h4>例題</h4>{#each item.workedExamples as ex}<p class="example-q">{ex.question||ex.q}</p>{#each ex.steps||[] as step,j}<p class="step">{j+1}. {step}</p>{/each}<p class="answer">答え：{ex.answer||ex.a}</p>{/each}{/if}{#if item.commonErrors?.length}<h4>間違えやすいポイント</h4><ul>{#each item.commonErrors as e}<li>{e}</li>{/each}</ul>{/if}{#if item.questionPatterns?.length}<h4>よく問われる視点</h4><ul>{#each item.questionPatterns as p}<li>{p}</li>{/each}</ul>{/if}{#if !item.keyTerms?.length&&!item.formulas?.length&&!item.workedExamples?.length&&!item.commonErrors?.length}<p>この項目の詳細ノートは準備中です。単元の索引として利用できます。</p>{/if}</div>{/if}
        </article>{/each}</div>
      {/if}
      <footer><a href="/">MANABIXX<span>.</span></a><span>KNOWLEDGE THAT MOVES YOU FORWARD.</span><a href="/releases/">更新履歴 <ArrowUpRight size={14}/></a></footer>
    </main>
  </div>
</div>
<style>
  :global(body){margin:0;background:var(--canvas);color:var(--ink);font-family:'DM Sans','Noto Sans JP',sans-serif}
  .study-app{--lib-bg:#090b0a;--lib-panel:#121613;--lib-panel2:#191f19;--lib-text:#eef2e9;--lib-muted:#9ca795;--lib-line:#2b342b;--lib-accent:#d4fa4c;min-height:100vh;background:var(--canvas);color:var(--ink)}
  :global(:root[data-theme='light']) .study-app{--lib-bg:#f4f4ef;--lib-panel:#fff;--lib-panel2:#e9ece4;--lib-text:#191b18;--lib-muted:#777d70;--lib-line:#dfe2d8;--lib-accent:#789d20}
  .rail{position:fixed;inset:0 auto 0 0;width:76px;background:#111510;color:#f4f5ed;display:flex;align-items:center;flex-direction:column;padding:22px 0 18px;z-index:30}.mark{width:39px;height:39px;border:1px solid #59604e;border-radius:12px;display:grid;place-items:center;position:relative;color:#d6ff55;font-size:18px;font-weight:900;letter-spacing:-2px}.mark i{position:absolute;width:5px;height:5px;border-radius:50%;background:#d6ff55;right:7px;top:7px}.rail-links{display:flex;flex-direction:column;gap:12px;margin-top:66px}.rail-link{width:42px;height:42px;border:0;border-radius:12px;background:transparent;color:#8e9583;display:grid;place-items:center;transition:.18s}.rail-link:hover,.rail-link.selected{background:#d4fb4d;color:#202519}.rail-bottom{margin-top:auto;display:flex;flex-direction:column;align-items:center;gap:17px}.rail-avatar{width:32px;height:32px;border-radius:50%;background:#343a2d;color:#d8ff58;display:grid;place-items:center;font-size:11px;font-weight:800}
  .workspace{margin-left:76px;min-height:100vh}.topline{height:64px;border-bottom:1px solid var(--lib-line);display:flex;align-items:center;justify-content:space-between;padding:0 clamp(22px,5vw,76px);background:var(--lib-bg);color:var(--lib-text)}.crumb{font-size:10px;font-weight:800;letter-spacing:1.5px}.crumb span{color:var(--lib-muted)}.crumb b{color:#59614f;margin:0 10px}.topline-right{display:flex;align-items:center;gap:20px}.live-dot{font-size:8px;letter-spacing:1.7px;font-weight:800;color:var(--lib-muted)}.live-dot:before{content:'';display:inline-block;width:6px;height:6px;border-radius:50%;background:#a9d735;margin:0 8px 1px 0}.theme-toggle{width:34px;height:34px;border:1px solid var(--lib-line);border-radius:50%;background:transparent;color:var(--lib-text);display:grid;place-items:center}
  .page-wrap{max-width:1440px;margin:auto;padding:0 clamp(22px,5vw,76px) 26px}.intro{min-height:270px;background:#171d16;color:#f4f5ed;margin-top:26px;border:1px solid #303a2d;border-radius:5px;position:relative;overflow:hidden;padding:43px 6.5%;display:flex;align-items:center;justify-content:space-between}.eyebrow{display:flex;align-items:center;gap:8px;color:#b6d56c;font-size:9px;letter-spacing:2px;font-weight:800}.intro h1{font-size:clamp(38px,4.5vw,62px);line-height:1.18;letter-spacing:-3px;margin:20px 0 13px;font-weight:750}.intro h1 em{font-style:normal;color:#d3fb4c}.intro p,.catalog-head p{font-size:11px;line-height:1.9;color:#aeb5a4;margin:0}.intro-mark{width:112px;height:112px;border:1px solid #4a5641;border-radius:24px;background:linear-gradient(145deg,#20291d,#151a14);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#d3fa4c}.intro-mark span{font-size:7px;letter-spacing:1.5px;font-weight:900}
  .overview{display:grid;grid-template-columns:repeat(4,1fr);background:var(--lib-panel);border:1px solid var(--lib-line);border-radius:9px;padding:18px 0;margin-top:16px}.overview>div{padding:0 23px;border-right:1px solid var(--lib-line)}.overview>div:last-child{border:0}.overview span,.overview small{display:block;font-size:7px;letter-spacing:1px;color:var(--lib-muted);font-weight:800}.overview strong{display:block;font-size:25px;letter-spacing:-1px;margin:5px 0 1px;color:var(--lib-text)}.catalog-head{display:flex;align-items:end;justify-content:space-between;margin:42px 0 16px}.catalog-head h2{font-size:22px;margin:8px 0 4px;color:var(--lib-text)}.result-count{font-size:22px;font-weight:900;color:var(--lib-accent)}.result-count small{font-size:9px;color:var(--lib-muted);font-weight:600}
  .filters{background:var(--lib-panel);border:1px solid var(--lib-line);border-radius:9px;padding:16px;margin-bottom:17px}.search{height:43px;border:1px solid var(--lib-line);border-radius:6px;display:flex;align-items:center;gap:10px;padding:0 12px;color:var(--lib-muted)}.search:focus-within{border-color:var(--lib-accent)}.search input{border:0;outline:0;background:transparent;color:var(--lib-text);width:100%;font-size:10px}.search input::placeholder{color:var(--lib-muted)}.search button{border:0;background:transparent;color:var(--lib-muted)}.filter-row{display:flex;align-items:end;gap:11px;margin-top:12px}.filter-row label{display:grid;gap:5px;font-size:8px;color:var(--lib-muted);font-weight:750}.filter-row select{min-width:130px;height:35px;padding:0 9px;border:1px solid var(--lib-line);border-radius:6px;background:var(--lib-bg);color:var(--lib-text);font-size:9px}.clear{margin-left:auto;border:0;background:transparent;color:var(--lib-muted);font-size:8px;display:flex;align-items:center;gap:6px;padding:10px}
  .cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.cards article{background:var(--lib-panel);border:1px solid var(--lib-line);border-radius:9px;padding:16px;min-width:0;transition:border-color .18s,transform .18s;color:var(--lib-text)}.cards article:hover{border-color:#728c50;transform:translateY(-2px)}.cards article.expanded{grid-column:span 2;border-color:var(--lib-accent)}.card-top{display:flex;align-items:center;gap:8px}.subject{display:inline-flex;align-items:center;gap:5px;padding:5px 7px;border-radius:5px;font-size:8px;font-weight:850}.subject.science{background:#1b3027;color:#8be0b4}.subject.social{background:#30271e;color:#e2b47e}.grade{font-size:7px;color:var(--lib-muted)}.save{margin-left:auto;border:0;background:transparent;color:var(--lib-muted);padding:4px}.save.bookmarked{color:var(--lib-accent)}.save.bookmarked :global(svg){fill:var(--lib-accent);stroke:var(--lib-accent)}.cards h3{font-size:14px;margin:14px 0 7px;letter-spacing:-.2px;color:var(--lib-text)}.description{font-size:9px;line-height:1.8;color:var(--lib-muted);min-height:34px;margin:0}.card-bottom{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--lib-line);margin-top:13px;padding-top:10px}.card-bottom>span{font-size:7px;letter-spacing:1px;color:var(--lib-muted);font-weight:850}.card-bottom>span.complete{color:var(--lib-accent)}.card-bottom button{border:0;background:transparent;color:var(--lib-accent);font-size:8px;font-weight:850;display:flex;align-items:center;gap:4px}
  .detail{border-top:1px solid var(--lib-line);margin-top:13px;padding-top:13px;grid-column:1/-1}.detail-title{font-size:8px;letter-spacing:1px;color:var(--lib-accent);font-weight:900}.detail h4{font-size:9px;margin:14px 0 7px;color:var(--lib-text)}.detail p,.detail li{font-size:9px;line-height:1.8;color:var(--lib-muted)}.terms{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.terms span{padding:8px;background:var(--lib-panel2);border-radius:6px;font-size:8px;color:var(--lib-text)}.terms b,.terms small{display:block}.terms small{color:var(--lib-muted);margin-top:3px}.example-q{font-weight:800;color:var(--lib-text)!important}.step{margin:2px 0!important}.answer{color:var(--lib-accent)!important;font-weight:800}.detail ul{padding-left:17px}.empty{min-height:220px;display:flex;align-items:center;justify-content:center;gap:12px;color:var(--lib-muted);font-size:10px;background:var(--lib-panel);border:1px dashed var(--lib-line);border-radius:9px}.loader{width:18px;height:18px;border:2px solid var(--lib-line);border-top-color:var(--lib-accent);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
  footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--lib-line);margin-top:42px;padding-top:17px;color:var(--lib-muted);font-size:7px;letter-spacing:1.2px}footer a:first-child{font-size:13px;color:var(--lib-text);font-weight:950}footer a:first-child span{color:var(--lib-accent)}footer a:last-child{display:flex;align-items:center;gap:4px;color:var(--lib-text);font-weight:800}
  @media(max-width:850px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.cards article.expanded{grid-column:span 2}.overview>div{padding:0 13px}.topline{padding:0 22px}}
  @media(max-width:580px){.rail{width:58px;padding-top:15px}.mark{width:35px;height:35px}.rail-links{margin-top:48px;gap:8px}.rail-link{width:38px;height:38px}.workspace{margin-left:58px}.topline{height:58px;padding:0 12px}.crumb{font-size:8px;letter-spacing:.7px}.crumb b{margin:0 4px}.live-dot{display:none}.topline-right{gap:8px}.page-wrap{padding:0 13px 22px}.intro{min-height:220px;padding:25px 19px;margin-top:14px}.intro-mark{width:65px;height:65px;border-radius:13px}.intro-mark :global(svg){width:21px}.intro-mark span{font-size:5px}.intro h1{font-size:29px;letter-spacing:-1.5px;margin:14px 0 8px}.intro p{font-size:9px;max-width:250px}.overview{grid-template-columns:repeat(2,1fr);gap:14px 0;padding:15px 0}.overview>div:nth-child(2){border:0}.overview>div:nth-child(3){padding-top:10px}.overview>div:nth-child(4){padding-top:10px}.overview strong{font-size:22px}.catalog-head{margin-top:31px}.catalog-head h2{font-size:19px}.filter-row{display:grid;grid-template-columns:1fr 1fr}.filter-row select{width:100%;min-width:0}.clear{margin:0;justify-content:start}.cards{grid-template-columns:1fr}.cards article.expanded{grid-column:span 1}.terms{grid-template-columns:1fr}footer{gap:10px;font-size:5px}footer span{display:none}}
</style>